  'Playback' => 'Ойнату',
  'Playback progress, watch-later state, likes, comments, subscriptions, notifications, and admin analytics are saved when linked to authenticated platform features.' => 'Ойнату барысы, кейін қарау күйі, ұнатулар, пікірлер, жазылымдар, хабарландырулар және әкімші талдаулары аутентификацияланған платформа мүмкіндіктерімен байланыстырылған кезде дерекқорда сақталады.',
  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'Ойнату, пікірлер, ұнатулар, кейінірек көру, жазылымдар, хабарландырулар, хабарлар, ойнату тізімдері және тіл параметрлері негізгі шарлау және есептік жазба мәзірі арқылы қолжетімді.',
  'PlayHub' => 'PlayHub',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'PlayHub – бір есептік жазбадан автор мазмұнын жүктеп салуға, көруге, жоспарлауға, басқаруға және модерациялауға арналған бейне платформасы.',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub – жасаушыларға, көрермендерге, қауымдастықтарға және платформа операторларына арналған осы орналастыруда жұмыс істейтін бейне платформасы.',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'PlayHub бір платформадан жасаушы арналарын, бейне жүктеп салуларды, жоспарланған жариялауды, жазылымдарды, пікірлерді, ойнату тізімдерін, кейінірек көруді, тікелей мазмұн беттерін және басқару құралдарын ұсынады.',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub кіру сеанстары, API аутентификациясы, CSRF/қауіпсіздік тәртібі, тіл таңдау, тақырып таңдау, тіркелгі мәзірінің күйі және қолданбаның жұмыс істеуі үшін қажетті басқа мүмкіндіктер үшін маңызды cookie файлдары мен шолғыш жадын пайдаланады.',
