  'Select one or more video files, enter required details, choose category and language, add a thumbnail, choose visibility, and publish. Large files are uploaded in chunks before the server starts processing.' => 'Бір немесе бірнеше бейне файлдарын таңдаңыз, қажетті мәліметтерді енгізіңіз, санат пен тілді таңдаңыз, нобай қосыңыз, көріну мүмкіндігін таңдаңыз және жариялаңыз. Үлкен файлдар сервер өңдеуді бастамас бұрын бөліктермен жүктеледі.',
