  'Sign in and use Settings for account, profile, password, notification, privacy, and creator preferences. Creator upload and content issues should include the video title, channel, browser, and any processing error shown on the upload page.' => 'Жүйеге кіріп, тіркелгі, профиль, құпия сөз, хабарландыру, құпиялылық және жасаушы қалаулары үшін Параметрлерді пайдаланыңыз. Автор жүктеп салу және мазмұн мәселелері бейне тақырыбын, арнаны, шолғышты және жүктеп салу бетінде көрсетілген кез келген өңдеу қатесін қамтуы керек.',
  'Sign in for account support' => 'Тіркелгіні қолдау үшін жүйеге кіріңіз',
