  'Taxonomies' => 'Таксономиялар',
  'Technical issue' => 'Техникалық мәселе',
  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'Ағымдағы PlayHub API және жүктеп салу жұмыс процесімен интеграцияға арналған техникалық ескертпелер.',
  'Tell us more about your question or request...' => 'Сұрағыңыз немесе сұрауыңыз туралы толығырақ айтып беріңіз...',
  'Terms of Use' => 'Пайдалану шарттары',
  'The configured' => 'Конфигурацияланған',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'Әзірлеуші ​​беті тікелей Laravel серверіне қосылған: маршрут тізімдемесі, дерекқор саны, жүктеп салу шектеулері және платформа метадеректері /api/developers сайтынан жүктеледі.',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'Frontend таңдалған тіл, тақырып, ойнату кезегі, көру барысы және интерфейс күйі сияқты теңшелімдерді сақтайды, осылайша тәжірибе бетті шарлау және қайта жүктеу кезінде тұрақты болып қалады.',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'Өңдеу тапсырмасы орындауды кодтайды, қажет болғанда нобайлар жасайды, субтитрлерді сақтайды және өңдеу аяқталған кезде бейнелерді дайын деп белгілейді. Болашақ жоспарланған бейнелер жоспарлаушы оларды шығарғанға дейін жеке болып қалады.',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'Жүктеп салу жүйесі дерекқормен қамтамасыз етілген, API санаттары мен тілдерін қолдайды, жүктеп салынған бейнелерді өңдейді, нобайлар мен жазбаларды сақтайды және жоспарланған мазмұнды оның шығарылым уақытына дейін құпия сақтайды.',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'Бұл бетте PlayHub сеанстар, қауіпсіздік, теңшелімдер, ойнату және аутентификацияланған мүмкіндіктер үшін cookie файлдары мен браузер жадын қалай пайдаланатынын түсіндіреді.',
