  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'Тікелей PlayHub деректерімен жүктеп салыңыз, көріңіз, жазылыңыз, модерациялаңыз және құрастырыңыз.',
  'Uploaded videos' => 'Жүктелген бейнелер',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'Жүктеп салынған бейнелер ойнатылатын трансляцияларға кодталған. Өңдеу уақыты файл өлшеміне, ұзақтығына, сервер жүктемесіне және кезек күйіне байланысты. Жүктеп салу беті мен Creator Studio бейне жазбасынан нақты өңдеу күйін көрсетеді.',
  'Uploads, scheduling, and processing are available.' => 'Жүктеп салулар, жоспарлау және өңдеу қол жетімді.',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => '/api/videos, арнаның соңғы нүктелері және автордың жұмыс процестері үшін аутентификацияланған маршруттарды пайдаланыңыз.',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'Әкімшілер нақты мазмұн сілтемесін алуы үшін бейнелер мен пікірлер үшін кірістірілген есеп әрекеттерін пайдаланыңыз. Әкімші бақылау тақтасының беттері пайдаланушылар, мазмұн, есептер, монетизация, аналитика, қолдау, рөлдер және жүйе параметрлері үшін тірі дерекқор деректерін пайдаланады.',
  'Use Contact Us' => 'Бізбен байланысуды пайдаланыңыз',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'Қалыпты API сұраулары үшін JSON және файлдарды жүктеп салу үшін FormData пайдаланыңыз. Тексеруді айналып өтпеңіз: санаттар мен тілдер дерекқор идентификаторлары болып табылады, көріну жалпыға қолжетімді, тізімде жоқ немесе жекемен шектеледі және субтитрлер SRT, VTT немесе TXT файлдарын қабылдайды.',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'Профильді, қауіпсіздікті, құпия сөзді, екі факторлы жеткізуді, құрылғыларды, қалауларды және хабарландыру опцияларын жаңарту үшін Параметрлерді пайдаланыңыз. Тіркелгіңізге кіре алмасаңыз, кіру ағынын пайдаланыңыз және сайт әкімшісіне тіркелгі электрондық поштасын беріңіз.',
  'Use the contact form' => 'Байланыс формасын пайдаланыңыз',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'Әкімшілер нақты мазмұн сілтемесін алу үшін бейнелер, пікірлер және қауымдастық жазбаларындағы есеп әрекеттерін пайдаланыңыз.',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'Мазмұн платформа ережелерін бұзуы мүмкін кезде бейнелер, пікірлер және қауымдастық жазбаларындағы есеп әрекеттерін пайдаланыңыз. Бұл есептер нақты мазмұн жазбасымен байланыстырылған және жалпы хабарға қарағанда жақсырақ, себебі әкімшілер нақты элементті қарай алады.',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'Тіркелгі анықтамасы, мазмұн есептері, техникалық мәселелер және әкімші сұраулары үшін дұрыс PlayHub арнасын пайдаланыңыз.',
  'Video categories' => 'Бейне санаттары',
  'Video for everyone. Built for creators and viewers.' => 'Барлығына арналған бейне. Нақты платформа деректерінен құрастырылған.',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'Бейнені жүктеп салу, жоспарлау, нобайлар және өңдеу мәселелері.',
  'Videos, thumbnails, captions, processing.' => 'Бейнелер, нобайлар, жазулар, өңдеу.',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'Көрермендер санаттарды шолып, бейнелерді іздей алады, мазмұнды көре алады, арналарға жазыла алады, кейінірек көру үшін бейнелерді сақтай алады, пікір жаза алады, хабарландырулар ала алады, тіл мен арнайы мүмкіндіктердің теңшелімдерін басқара алады.',
  'Viewing and community help' => 'Қарау және қауымдастық көмегі',
  'Waiting for backend endpoint inventory.' => 'Соңғы нүкте түгендеу күтілуде.',
  'We’re here to help.' => 'Біз көмектесу үшін осындамыз.',
  'What is PlayHub?' => 'PlayHub дегеніміз не?',
  'What PlayHub does' => 'PlayHub не істейді',
  'Where do contact messages go?' => 'Байланыс хабарламалары қайда барады?',
  'Why is my video still processing?' => 'Неліктен бейнем әлі өңделуде?',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'Иә. Жүктеп салу бетіндегі негізгі кесте күні мен уақыт өрісін пайдаланыңыз. Backend жоспарланған_at сақтайды, бейнені өңдейді, күн болашақта болған кезде оны құпия сақтайды және Laravel жоспарлаушысы жоспарланған уақыттан кейін іске қосылғанда оны шығарады.',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'Иә. Жүктеп салуда жергілікті кесте өрісін пайдаланыңыз. Backend жоспарланған_at сақтайды және кесте уақытына жеткенде өңдеуден кейін бейнені шығарады.',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'Сіз қонақ ретінде қарап жатырсыз. Тіркелгіге арналған құралдарға қол жеткізу үшін жүйеге кіріңіз.',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'Сіз тіркелгіңіздің тіркелгі деректеріне, профиль әрекетіне, жүктеп салынған мазмұнға, пікірлерге, хабарларға және тіркелгіңізден жасалған кез келген жасаушы немесе әкімші әрекеттеріне жауаптысыз. Күшті құпия сөздерді пайдаланыңыз және екі факторлы жеткізу әдістерін ағымдағы ұстаңыз.',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'Браузер параметрлерінде шолғыш cookie файлдарын және жергілікті жадты өшіруге болады. Маңызды жадты тазалау жүйеден шығуы, тіл/тақырып теңшелімдерін қалпына келтіру, жергілікті ойнату күйін жою және жүйеге қайта кіруді талап етуі мүмкін.',
  'You receive a response by email.' => 'Сіз электрондық пошта арқылы жауап аласыз.',
  'You’re in control' => 'Сіз бақылаудасыз',
  'Your choices' => 'Сіздің таңдауларыңыз',
  'Your message is saved directly in the website backend and appears in the admin dashboard under Support.' => 'Сіздің хабарламаңыз тікелей веб-сайт серверінде сақталады және әкімші бақылау тақтасында Қолдау астында көрсетіледі.',
  'Your support' => 'Сіздің қолдауыңыз',
