  'Upload planner' => 'Жүктеп салуды жоспарлаушы',
  'Start a new upload with titles, tags, visibility, and thumbnail steps.' => 'Тақырыптар, тегтер, көріну және нобай қадамдары бар жаңа жүктеп салуды бастаңыз.',
  'Shorts studio' => 'Шорттар студиясы',
  'Create short videos for faster discovery and mobile viewers.' => 'Жылдамырақ табу және мобильді көрермендер үшін қысқа бейнелер жасаңыз.',
